// The helper every service uses to call Go. Calls go through the bindings Wails generates in
// wailsjs/go/main/App (regenerated by `wails dev`, `wails build` and `wails generate module`);
// request() adds the interceptors and turns Wails' string rejections into Errors.
import type { Endpoint } from './endpoints';
import { interceptors, toError, type RequestContext } from './interceptors';

/** Thrown when the Wails bindings are missing: the page is not running inside the desktop app. */
export class BackendUnavailableError extends Error {
  constructor() {
    super('The desktop backend is not available. Start the app with "wails dev" or the packaged binary.');
    this.name = 'BackendUnavailableError';
  }
}

/** Whether the page runs inside Wails (window.go.main.App is injected by the desktop app). */
export function backendAvailable(): boolean {
  return !!window.go?.main?.App;
}

/**
 * Calls one Go method through its generated binding, e.g.
 * `request<Run>(Endpoint.GetRun, () => App.GetRun(id))`. The endpoint names the call for the
 * interceptors; T is the result type in the shapes of '@/types'.
 */
export async function request<T>(endpoint: Endpoint, call: () => Promise<unknown>): Promise<T> {
  const ctx: RequestContext = { endpoint };
  try {
    if (!backendAvailable()) throw new BackendUnavailableError();
    for (const fn of interceptors.request.all()) await fn(ctx);
    let data = await call();
    for (const fn of interceptors.response.all()) data = await fn(data, ctx);
    return data as T;
  } catch (e) {
    let error = toError(e);
    for (const fn of interceptors.error.all()) {
      try {
        // An error interceptor that returns instead of throwing recovers the call.
        return (await fn(error, ctx)) as T;
      } catch (next) {
        error = toError(next);
      }
    }
    throw error;
  }
}

/**
 * Passes a '@/types' value to a generated binding. The generated parameter types are the model
 * classes in wailsjs/go/models.ts; '@/types' describes the same JSON as plain interfaces, and
 * Wails sends plain JSON either way, so only the compile-time type differs.
 */
export function wire<T>(value: T): never {
  return value as never;
}

export function errorMessage(e: unknown): string {
  return e instanceof Error ? e.message : String(e);
}

declare global {
  interface Window {
    go?: { main?: { App?: Record<string, (...args: unknown[]) => Promise<unknown>> } };
  }
}
